INSERT INTO `sys_operate_record` VALUES (37289, 28, 'POST', '公司业务', NULL, '127.0.0.1', '[{\"equalsTaxNumber\":\"\",\"flagEquals\":[],\"likeName\":\"\",\"selectSQLInfo\":{\"entityClass\":\"com.tbs.shared.pojo.entity.SystemCompanyEntity\",\"rawSql\":\"SELECT *FROM (SELECT d.*,             CASE WHEN n.parent_id IS NULL THEN 1 ELSE 0 END AS tree_root_flag      FROM sys_company d               LEFT JOIN tree_node n ON n.entity_id = d.id AND n.group_name LIKE \'COT:%\') AS temp\"},\"sqlPrefix\":\"sql/\",\"sqlSuffix\":\".sql\",\"treeRootFlag\":1},1,10]', '{\"map\":{\"message\":\"操作成功\",\"data\":{\"data\":[{\"childrenCount\":0,\"companyName\":\"系统公司\",\"flag\":5,\"id\":1,\"logoImage\":\"系统公司\",\"taxNumber\":\"系统公司\",\"updateTime\":\"2026-05-12 13:09:52\"},{\"childrenCount\":1,\"companyName\":\"杭州新港润滑科技有限公司\",\"createTime\":\"2025-09-03 12:20:00\",\"description\":\"杭州新港润滑科技有限公司 (曾用名：杭州新港石油化工有限公司) ，成立于1993年，位于浙江省杭州市，是一家以从事石油、煤炭及其他燃料加工业为主的企业\",\"flag\":1,\"id\":2,\"logoImage\":\"https://omo-oss-image.thefastimg.com/portal-saas/new2023101113095128628/cms/image/e5546f92-c3f6-43c5-8fd4-9243bf5cae36.png\",\"taxNumber\":\"913301006091289797\",\"updateTime\":\"2025-10-23 18:29:54\"},{\"childrenCount\":0,\"companyName\":\"测试部门A\",\"createTime\":\"2026-05-12 13:26:39\",\"description\":\"\",\"flag\":2,\"id\":14,\"taxNumber\":\"测试部门A\"}],\"total\":3},\"code\":200}}', '2026-05-12 13:32:04', 'com.tbs.app.controller.privates.AdminCompanyController.query', '/private/admin/company/query', '223344', NULL, NULL, NULL);
